import Navigation from "../../navigationpage"
import {React, Suspense } from "react"
// import Home from "../home"
// import RoomCarts from "../roomcarts"
// import FoodCards from "../foodcards"
import BlurHome from "./defaultresort/mainhome/blurHome";
const LazyHome = React.lazy( () => import('../home') )
const LazyRoomCart = React.lazy( () => import('../roomcarts') ) 
const LazyCards = React.lazy( () => import('../foodcards '))

const MainHome = () => {
    return(
        <div>
            <Navigation />
            <Suspense fallback={<BlurHome />} > <Home/> </Suspense>
            <RoomCarts />
            <FoodCards />
        </div>
    )
}

export default MainHome
